// Files are named 'X.jsx' (in lib/ or src/) or 'pickup/X.jsx'.
const src = (file) => SOURCES[`../lib/${file}`] ?? SOURCES[`../${file}`] ?? ''

// Categories kept in the code but not shown on the site. Their components and
// files stay as they are; take a category out of this list to show it again.
export const HIDDEN_CATEGORIES = ['Icons & Emojis']
// Individual components kept in the code but left out of the site (the
// sidebar, the section pages, search and the generated registry files).
export const HIDDEN_COMPONENTS = ['shirt', 'earbuds', 'gamepad']

const ALL_CATEGORIES = ['Text', 'Animation', 'UI', 'Phone UI', '3D & Materials', 'Backgrounds', 'Motion Graphics', 'Icons & Emojis']
export const CATEGORIES = ALL_CATEGORIES.filter((c) => !HIDDEN_CATEGORIES.includes(c))

// The UI section is grouped by visual style, in this order.
export const UI_STYLES = ['Flat', 'Glassmorphism', 'Neumorphism', 'Liquid glass', 'Bento', 'Minimalism', 'Maximalism', 'Skeuomorphism']

export const ICON_STYLES = ['Icons', 'Emojis']

// sections of the 3D & Materials category, in the order they are shown
export const OBJECT_STYLES = ['Tech & gadgets', 'Music & audio', 'Sports & fitness', 'Fashion & wear', 'Desk & stationery', 'Tools & gear', 'Everyday objects', 'Physics & play', 'Vehicles', 'Nature & world']

// Basic outline icons share one set of controls; each file is standalone.
const icon = (Comp, file, slug, name, description) => ({
  slug: `${slug}-icon`,
  name: `${name} Icon`,
  category: 'Icons & Emojis',
  style: 'Icons',
  isNew: true,
  description,
  controls: [
    { name: 'size', type: 'range', min: 12, max: 128, step: 2, default: 24, unit: 'px' },
    { name: 'strokeWidth', type: 'range', min: 0.5, max: 3, step: 0.25, default: 1.75 },
    { name: 'color', type: 'color', default: '#15171a' },
  ],
  preview: (p) => <Comp {...p} />,
  files: [file],
  deps: [],
})

// Filled, full-colour emojis: each file is standalone and only takes a size.
const emoji = (Comp, file, slug, name, description) => ({
  slug: `${slug}-emoji`,
  name: `${name} Emoji`,
  category: 'Icons & Emojis',
  style: 'Emojis',
  isNew: true,
  description,
  controls: [{ name: 'size', type: 'range', min: 16, max: 256, step: 4, default: 96, unit: 'px' }],
  preview: (p) => <Comp {...p} />,
  files: [file],
  deps: [],
})

